// frontend/src/features/tickets/TicketCreate.jsx - Enhanced UI Version (Inspired by Sanchar Helpdesk PDF)
import React, { useState } from "react";
import api from "../../api/axios"; // Adjust path if needed
import { useNavigate } from "react-router-dom";
import { useSelector } from "react-redux"; // To get auth token/user if required

const TicketCreate = () => {
  const [form, setForm] = useState({
    subject: "",
    rank: "",
    name: "",
    serviceNumber: "",
    sancharNodeName: "",
    paxNoTelephoneNo: "",
    ncnNo: "",
    location: "",
    severity: "LOW",
    parentComnetcen: "",
    description: "",
    priority: "NORMAL",
  });
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  // Optional: Get current user from Redux (if backend requires creator info)
  const user = useSelector((state) => state.auth.user);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const data = new FormData();
      data.append("subject", form.subject); // Matched to PDF 'Subject'
      data.append("rank", form.rank);
      data.append("name", form.name);
      data.append("service_number", form.serviceNumber); // Snake case for backend
      data.append("sanchar_node_name", form.sancharNodeName);
      data.append("pax_no_telephone_no", form.paxNoTelephoneNo);
      data.append("ncn_no", form.ncnNo);
      data.append("location", form.location);
      data.append("severity", form.severity);
      data.append("parent_comnetcen", form.parentComnetcen);
      data.append("description", form.description);
      data.append("priority", form.priority);
      if (file) data.append("attachment", file); // Match your backend field name

      // Optional: If backend expects creator or other fields
      // data.append("creator", user?.id); // If not auto-set by backend

      await api.post("/tickets/", data, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      // Success: Redirect to employee dashboard
      navigate("/employee");
    } catch (err) {
      console.error("Ticket creation error:", err);
      setError(
        err.response?.data?.detail ||
          err.response?.data?.message ||
          "Failed to create ticket. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  const isFormValid = () => {
    return (
      form.subject &&
      form.rank &&
      form.name &&
      form.serviceNumber &&
      form.sancharNodeName &&
      form.location &&
      form.description
    );
  };

  return (
    <div style={styles.container}>
      <h3 style={styles.title}>Create New Sanchar Ticket</h3>

      {error && <div style={styles.errorAlert}>{error}</div>}

      <form onSubmit={handleSubmit} style={styles.form}>
        {/* Ticket Raised By Section */}
        <div style={styles.section}>
          <h4 style={styles.sectionTitle}>Ticket Raised By</h4>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Rank *</label>
            <input
              type="text"
              name="rank"
              style={styles.input}
              placeholder="Enter rank"
              value={form.rank}
              onChange={handleChange}
              required
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Name *</label>
            <input
              type="text"
              name="name"
              style={styles.input}
              placeholder="Enter name"
              value={form.name}
              onChange={handleChange}
              required
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Service Number *</label>
            <input
              type="text"
              name="serviceNumber"
              style={styles.input}
              placeholder="Enter service number"
              value={form.serviceNumber}
              onChange={handleChange}
              required
            />
          </div>
        </div>

        {/* Sanchar Details Section */}
        <div style={styles.section}>
          <h4 style={styles.sectionTitle}>Sanchar Details</h4>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Subject *</label>
            <input
              type="text"
              name="subject"
              style={styles.input}
              placeholder="Enter ticket subject"
              value={form.subject}
              onChange={handleChange}
              required
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Sanchar Node Name *</label>
            <input
              type="text"
              name="sancharNodeName"
              style={styles.input}
              placeholder="Enter Sanchar node username"
              value={form.sancharNodeName}
              onChange={handleChange}
              required
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>PAX No. and Telephone No.</label>
            <input
              type="text"
              name="paxNoTelephoneNo"
              style={styles.input}
              placeholder="Enter PAX and telephone numbers"
              value={form.paxNoTelephoneNo}
              onChange={handleChange}
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>NCN No.</label>
            <input
              type="text"
              name="ncnNo"
              style={styles.input}
              placeholder="Enter NCN number"
              value={form.ncnNo}
              onChange={handleChange}
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Location *</label>
            <input
              type="text"
              name="location"
              style={styles.input}
              placeholder="Enter location of issue"
              value={form.location}
              onChange={handleChange}
              required
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Parent COMNETCEN</label>
            <input
              type="text"
              name="parentComnetcen"
              style={styles.input}
              placeholder="Enter parent COMNETCEN"
              value={form.parentComnetcen}
              onChange={handleChange}
            />
          </div>
        </div>

        {/* Issue Details Section */}
        <div style={styles.section}>
          <h4 style={styles.sectionTitle}>Issue Details</h4>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Severity</label>
            <select
              name="severity"
              style={styles.select}
              value={form.severity}
              onChange={handleChange}
            >
              <option value="LOW">Low</option>
              <option value="MEDIUM">Medium</option>
              <option value="HIGH">High</option>
            </select>
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Priority</label>
            <select
              name="priority"
              style={styles.select}
              value={form.priority}
              onChange={handleChange}
            >
              <option value="LOW">Low</option>
              <option value="NORMAL">Normal</option>
              <option value="HIGH">High</option>
              <option value="VERY_HIGH">Very High</option>
            </select>
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Description *</label>
            <textarea
              name="description"
              style={styles.textarea}
              rows="6"
              placeholder="Describe the issue in detail..."
              value={form.description}
              onChange={handleChange}
              required
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Attach Evidence (Image/PDF)</label>
            <input
              type="file"
              style={styles.fileInput}
              accept="image/*,.pdf"
              onChange={(e) => setFile(e.target.files[0])}
            />
            <small style={styles.smallText}>
              Optional: Upload screenshot or error log (max 5MB recommended)
            </small>
          </div>
        </div>

        <button
          type="submit"
          style={{
            ...styles.submitButton,
            opacity: loading || !isFormValid() ? 0.7 : 1,
          }}
          disabled={loading || !isFormValid()}
        >
          {loading ? "Submitting..." : "Submit Ticket"}
        </button>
      </form>
    </div>
  );
};

